/*
 * A357875  Numbers whose run-sums of prime indices are weakly increasing.
 * https://oeis.org/A357875
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n‑th positive integer whose run‑sums of prime indices
 *            are weakly increasing. (Run‑sums are the products index*exponent
 *            for each distinct prime factor, listed in increasing prime
 *            order. The sequence is generated by testing consecutive
 *            candidates.)
 * Range:     u8 n <= 67, u16 n <= 67, u32 n <= 67, u64 n <= 67, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

/* ---------- Prime table utilities ----------------------------------- */
static uint64_t *primes = NULL;          /* array of primes */
static size_t   prime_cnt = 0;           /* number of primes generated */
static size_t   prime_cap = 0;           /* capacity of the primes array   */
static size_t   prime_sieve_limit = 0;   /* current sieve limit */

/* Simple binary search for the 1‑based index of prime p in `primes` */
static inline size_t prime_index(uint64_t p)
{
    size_t lo = 0, hi = prime_cnt;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (primes[mid] == p) return mid + 1; /* 1‑based */
        if (primes[mid] < p) lo = mid + 1;
        else                hi = mid;
    }
    return 0;           /* should never happen for a prime factor */
}

/* Integer square root by binary search (avoids floating point). */
static inline uint64_t int_sqrt_u64(uint64_t n)
{
    uint64_t lo = 0, hi = (n < 0x100000000ULL) ? n : 0xFFFFFFFFULL;
    while (lo < hi) {
        uint64_t mid = (lo + hi + 1) >> 1;
        if (mid > 0 && mid > n / mid) hi = mid - 1;
        else                          lo = mid;
    }
    return lo;
}

/* Build the prime list up to `limit` by a simple Eratosthenes sieve. */
static void build_prime_table(size_t limit)
{
    if (prime_sieve_limit >= limit) return;   /* already built */

    /* Allocate sieve bitmap */
    unsigned char *sieve = (unsigned char*)calloc(limit + 1, 1);
    if (!sieve) abort();

    /* Rough upper bound for number of primes up to `limit`.
       p(n) ~ n / log n   => use limit/15 as safe overestimate for all limits used. */
    size_t estimated = limit / 15 + 10;
    if (prime_cap < estimated) {
        primes = (uint64_t*)realloc(primes, estimated * sizeof(uint64_t));
        if (!primes) abort();
        prime_cap = estimated;
    }

    prime_cnt = 0;
    for (size_t i = 2; i <= limit; ++i) {
        if (!sieve[i]) {                     /* i is prime */
            if (prime_cnt == prime_cap) {    /* grow array if needed */
                prime_cap *= 2;
                primes = (uint64_t*)realloc(primes, prime_cap * sizeof(uint64_t));
                if (!primes) abort();
            }
            primes[prime_cnt++] = i;

            if (i <= limit / i) {            /* mark composites */
                for (size_t j = i * i; j <= limit; j += i) sieve[j] = 1;
            }
        }
    }
    free(sieve);
    prime_sieve_limit = limit;
}

/* Smallest prime factor of n (uses the prime table). */
static uint64_t smallest_prime_factor(uint64_t n)
{
    if (n <= 1) return n;
    uint64_t limit = int_sqrt_u64(n);
    build_prime_table(limit);
    for (size_t i = 0; i < prime_cnt && primes[i] <= limit; ++i) {
        if (n % primes[i] == 0) return primes[i];
    }
    return n;  /* n itself is prime */
}

/* ---------- Check property for a single number --------------------- */
static bool good_number(uint64_t n)
{
    if (n == 1) return true;   /* 1 has no prime indices → property holds */

    uint64_t tmp = n;
    uint64_t prev_prod = 0;
    bool first_run = true;

    while (tmp > 1) {
        uint64_t p = smallest_prime_factor(tmp);
        int exp = 0;
        while (tmp % p == 0) { tmp /= p; ++exp; }

        build_prime_table(p);          /* ensure prime list contains p */
        size_t idx = prime_index(p);   /* 1‑based index of prime p */

        uint64_t prod = idx * (uint64_t)exp;   /* run‑sum for this prime */

        if (!first_run && prod < prev_prod) return false;
        prev_prod = prod;
        first_run = false;
    }
    return true;
}

/* ---------- Sequence storage and generation ------------------------ */
static seq_t *seq_vals = NULL;
static size_t seq_len = 0;
static size_t seq_cap = 0;
static uint64_t next_candidate = 1;

/* Ensure seq_vals has enough capacity for at least `need` elements. */
static void ensure_seq_capacity(size_t need)
{
    if (need <= seq_cap) return;
    size_t new_cap = (seq_cap == 0) ? 64 : seq_cap * 2;
    while (new_cap < need) new_cap <<= 1;
    seq_vals = (seq_t*)realloc(seq_vals, new_cap * sizeof(seq_t));
    if (!seq_vals) abort();
    seq_cap = new_cap;
}

/* --------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;                 /* undefined for 0 */

    size_t target = (size_t)n;                   /* convert to size_t for array */
    ensure_seq_capacity(target);

    while (seq_len < target) {
        if (good_number(next_candidate)) {
            seq_vals[seq_len++] = (seq_t)next_candidate;
        }
        ++next_candidate;
    }

    return seq_vals[target - 1];
}
